package online.rollnexa.service;
import online.rollnexa.api.ApiException; import online.rollnexa.api.Dto.*; import online.rollnexa.domain.*; import online.rollnexa.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class ScheduleServiceTest {
 @Mock AvailabilityRepository availability; @Mock GameSessionRepository sessions; @Mock SessionResponseRepository responses; @Mock RoomRepository rooms; @Mock RoomMemberRepository members; @Mock RoomService roomService; @Mock ViewMapper mapper;
 @Test void rejectsPastAvailability(){var user=new User();user.setId(1L);var service=new ScheduleService(availability,sessions,responses,rooms,members,roomService,mapper);assertThatThrownBy(()->service.vote(2L,user,new AvailabilityInput(LocalDate.now().minusDays(1),null,null,true))).isInstanceOf(ApiException.class).extracting("code").isEqualTo("PAST_DATE");verify(roomService).requireMember(2L,1L);}
 @Test void rejectsInvalidTimeRange(){var user=new User();user.setId(1L);var service=new ScheduleService(availability,sessions,responses,rooms,members,roomService,mapper);assertThatThrownBy(()->service.vote(2L,user,new AvailabilityInput(LocalDate.now().plusDays(1),LocalTime.of(22,0),LocalTime.of(20,0),true))).isInstanceOf(ApiException.class).extracting("code").isEqualTo("INVALID_TIME_RANGE");}
 @Test @SuppressWarnings("unchecked") void calendarCountsCoincidence(){var day=LocalDate.now().plusDays(2);var a=new Availability();a.setDate(day);a.setAvailable(true);a.setUser(new User());var b=new Availability();b.setDate(day);b.setAvailable(true);b.setUser(new User());when(availability.findByRoomIdAndDateBetweenOrderByDateAsc(2L,day,day)).thenReturn(List.of(a,b));when(members.countByRoomId(2L)).thenReturn(3L);var user=new User();user.setId(1L);var service=new ScheduleService(availability,sessions,responses,rooms,members,roomService,mapper);var result=service.calendar(2L,user,day,day);var summary=(List<AvailabilityDay>)result.get("summary");assertThat(summary).singleElement().satisfies(s->{assertThat(s.available()).isEqualTo(2);assertThat(s.total()).isEqualTo(3);});}
}
